select *
from user_money_details
where user_id = #{userId}

    and language_type = #{languageType}

order by create_time desc

        select * from `user_money_details` u where 1=1
        
            and u.user_id = #{userId}
        

        
            and u.classify = #{classify}
        
        
            and u.type = #{type}
        
        
            and u.shop_id = #{shopId}
        
        
            and date_format(create_time,'%Y-%m-%d') BETWEEN #{startTime} and #{endTime}
        
        
            and date_format(create_time,'%Y-%m-%d') >= #{startTime}
        
        
            and date_format(create_time,'%Y-%m-%d') <= #{endTime}
        
        order by create_time desc

select ifnull(sum(money),0) from user_money_details d where 1=1 and d. shop_id = #{shopId}

    and date_format(create_time,'%Y-%m-%d') BETWEEN #{startTime} and #{endTime}


    and date_format(create_time,'%Y-%m-%d') >= #{startTime}


    and date_format(create_time,'%Y-%m-%d') <= #{endTime}
